<body>
  <div class="todo-container">
    <div class="header">
      <h1>My Todos</h1>
    </div>

    <div class="input-area">
      <input type="text" id="new-todo" placeholder="What needs to be done?" />
      <button id="add-todo">Add</button>
    </div>

    <div class="filters">
      <button class="filter-btn active" data-filter="all">All</button>
      <button class="filter-btn" data-filter="active">Active</button>
      <button class="filter-btn" data-filter="completed">Completed</button>
    </div>

    <div class="todo-list" id="todo-list">
      <!-- Todos rendered here -->
    </div>

    <div class="stats" id="stats"></div>
  </div>

  <script>
    // Initialize from localStorage or empty array
    let todos = JSON.parse(localStorage.getItem('todos')) || [];

    const todoList = document.getElementById('todo-list');
    const newTodoInput = document.getElementById('new-todo');
    const addTodoBtn = document.getElementById('add-todo');
    const filterBtns = document.querySelectorAll('.filter-btn');
    const statsEl = document.getElementById('stats');

    // Render todos based on current filter
    function renderTodos(filter = 'all') {
      todoList.innerHTML = '';

      let filteredTodos = todos;

      if (filter === 'active') {
        filteredTodos = todos.filter(t => !t.completed);
      } else if (filter === 'completed') {
        filteredTodos = todos.filter(t => t.completed);
      }

      if (filteredTodos.length === 0) {
        todoList.innerHTML = '<div class="empty-state">No todos found</div>';
        updateStats();
        return;
      }

      filteredTodos.forEach((todo, index) => {
        const todoEl = document.createElement('div');
        todoEl.className = `todo-item${todo.completed ? ' completed' : ''}`;
        todoEl.innerHTML = `
          <input type="checkbox" class="todo-checkbox" ${todo.completed ? 'checked' : ''} data-index="${index}">
          <span class="todo-text">${escapeHtml(todo.text)}</span>
          <button class="delete-btn" data-index="${index}">×</button>
        `;
        todoList.appendChild(todoEl);
      });

      updateStats();
    }

    // Escape HTML special characters
    function escapeHtml(text) {
      const div = document.createElement('div');
      div.textContent = text;
      return div.innerHTML;
    }

    // Add a new todo
    function addTodo() {
      const text = newTodoInput.value.trim();
      if (!text) return;

      todos.push({ text, completed: false });
      saveTodos();
      newTodoInput.value = '';
      renderTodos(document.querySelector('.filter-btn.active').dataset.filter);
    }

    // Toggle todo completion
    function toggleTodo(index) {
      todos[index].completed = !todos[index].completed;
      saveTodos();
      renderTodos(document.querySelector('.filter-btn.active').dataset.filter);
    }

    // Delete a todo
    function deleteTodo(index) {
      todos.splice(index, 1);
      saveTodos();
      renderTodos(document.querySelector('.filter-btn.active').dataset.filter);
    }

    // Save todos to localStorage
    function saveTodos() {
      localStorage.setItem('todos', JSON.stringify(todos));
    }

    // Update stats display
    function updateStats() {
      const activeCount = todos.filter(t => !t.completed).length;
      const completedCount = todos.filter(t => t.completed).length;

      if (todos.length === 0) {
        statsEl.innerHTML = '';
        return;
      }

      statsEl.innerHTML = `${todos.length} ${todos.length === 1 ? 'item' : 'items'}${activeCount > 0 ? `, ${activeCount} ${activeCount === 1 ? 'active' : 'active'} remaining` : ''}`;
    }

    // Event listeners
    addTodoBtn.addEventListener('click', addTodo);

    newTodoInput.addEventListener('keypress', (e) => {
      if (e.key === 'Enter') {
        addTodo();
      }
    });

    // Delegated event listener for todo list
    todoList.addEventListener('click', (e) => {
      const index = e.target.dataset.index;

      if (e.target.classList.contains('todo-checkbox')) {
        toggleTodo(parseInt(index));
      } else if (e.target.classList.contains('delete-btn')) {
        deleteTodo(parseInt(index));
      }
    });

    // Delegated event listener for filter buttons
    document.querySelector('.filters').addEventListener('click', (e) => {
      if (e.target.classList.contains('filter-btn')) {
        filterBtns.forEach(btn => btn.classList.remove('active'));
        e.target.classList.add('active');
        renderTodos(e.target.dataset.filter);
      }
    });

    // Initial render
    renderTodos();
  </script>
</body>
</html>"}
